15	// Compile-time assertion that ClaudeCodeAgent satisfies ToolCallWalker.
16	var _ agent.ToolCallWalker = (*ClaudeCodeAgent)(nil)
17	
18	// WalkToolCalls reads Claude Code's JSONL transcript and returns one
19	// ToolCall per tool_use block. Missing or empty files yield (nil, nil)
20	// so activity-layer callers can treat absence as "no data" without
21	// branching on os.IsNotExist.
22	func (c *ClaudeCodeAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
23		if path == "" {
24			return nil, nil
25		}
26		f, err := os.Open(path) //nolint:gosec // path comes from session state written by the CLI
27		if err != nil {
28			if errors.Is(err, fs.ErrNotExist) {
29				return nil, nil
30			}
31			return nil, fmt.Errorf("open transcript: %w", err)
32		}
33		defer f.Close()
34	
35		scanner := bufio.NewScanner(f)
36		scanner.Buffer(make([]byte, 1<<20), 1<<24) // 16 MiB per line — tool_result payloads can be large
37	
38		type lineShape struct {
39			Type      string    `json:"type"`
40			Timestamp time.Time `json:"timestamp"`
41			Message   struct {
42				Content []struct {
43					Type  string          `json:"type"`
44					Name  string          `json:"name,omitempty"`
45					Input json.RawMessage `json:"input,omitempty"`
46				} `json:"content"`
47			} `json:"message"`
48		}
49	
50		var calls []agent.ToolCall
51		for scanner.Scan() {
52			var l lineShape
53			if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
54				continue
55			}
56			for _, block := range l.Message.Content {
57				if block.Type != "tool_use" {
58					continue
59				}
60				calls = append(calls, agent.ToolCall{
61					Name:        block.Name,
62					BashCommand: bashCommandFromInput(block.Input),
63					Timestamp:   l.Timestamp,
64				})
65			}
66		}
67		if err := scanner.Err(); err != nil {
68			return calls, fmt.Errorf("scan transcript: %w", err)
69		}
70		return calls, nil
71	}
72	
73	func bashCommandFromInput(raw json.RawMessage) string {
74		if len(raw) == 0 {
75			return ""
76		}
77		var v struct {
78			Command string `json:"command,omitempty"`
79		}
80		if err := json.Unmarshal(raw, &v); err != nil {
81			return ""
82		}
83		return v.Command
84	}
