16	// Compile-time assertion that CodexAgent satisfies ToolCallWalker.
17	var _ agent.ToolCallWalker = (*CodexAgent)(nil)
18	
19	// WalkToolCalls reads Codex's rollout JSONL and returns one ToolCall per
20	// tool-invoking response_item (function_call, custom_tool_call,
21	// local_shell_call, web_search_call). Token-count events, reasoning
22	// blocks, messages, and *_output entries are skipped — those are either
23	// internal state or result pairs of earlier calls.
24	func (c *CodexAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
25		if path == "" {
26			return nil, nil
27		}
28		f, err := os.Open(path) //nolint:gosec // path comes from session state written by the CLI
29		if err != nil {
30			if errors.Is(err, fs.ErrNotExist) {
31				return nil, nil
32			}
33			return nil, fmt.Errorf("open transcript: %w", err)
34		}
35		defer f.Close()
36	
37		scanner := bufio.NewScanner(f)
38		scanner.Buffer(make([]byte, 1<<20), 1<<24)
39	
40		var calls []agent.ToolCall
41		for scanner.Scan() {
42			var line rolloutLine
43			if err := json.Unmarshal(scanner.Bytes(), &line); err != nil {
44				continue
45			}
46			if line.Type != rolloutLineTypeResponseItem {
47				continue
48			}
49			var payload responseItemPayload
50			if err := json.Unmarshal(line.Payload, &payload); err != nil {
51				continue
52			}
53			call, ok := toolCallFromPayload(payload, line.Timestamp)
54			if !ok {
55				continue
56			}
57			calls = append(calls, call)
58		}
59		if err := scanner.Err(); err != nil {
60			return calls, fmt.Errorf("scan transcript: %w", err)
61		}
62		return calls, nil
63	}
64	
65	// toolCallFromPayload recognizes the four Codex tool-call payload shapes
66	// and returns a normalized ToolCall. Unknown payload types (messages,
67	// reasoning, token_count, *_output) return ok=false.
68	func toolCallFromPayload(p responseItemPayload, rawTimestamp string) (agent.ToolCall, bool) {
69		// Timestamp parse failures fall back to zero time — tool count is
70		// still accurate, only per-call duration attribution suffers.
71		ts, err := time.Parse(time.RFC3339, rawTimestamp)
72		if err != nil {
73			ts = time.Time{}
74		}
75	
76		switch p.Type {
77		case "function_call":
78			// Name is the concrete tool (exec_command, read_file, shell, …).
79			// For exec_command, arguments is a JSON string with a cmd field.
80			return agent.ToolCall{
81				Name:        p.Name,
82				BashCommand: commandFromFunctionArgs(p.Name, p.Arguments),
83				Timestamp:   ts,
84			}, true
85		case "local_shell_call":
86			return agent.ToolCall{
87				Name:        "local_shell",
88				BashCommand: commandFromFunctionArgs("local_shell", p.Arguments),
89				Timestamp:   ts,
90			}, true
91		case "custom_tool_call":
92			return agent.ToolCall{Name: p.Name, Timestamp: ts}, true
93		case "web_search_call":
94			return agent.ToolCall{Name: "web_search", Timestamp: ts}, true
95		}
96		return agent.ToolCall{}, false
97	}
98	
99	// commandFromFunctionArgs extracts the shell command string from the
100	// arguments JSON for tools whose first arg is a command. Codex's
101	// exec_command uses {"cmd":"…"}; other tools may not have a command.
102	const toolNameExecCommand = "exec_command"
103	
104	func commandFromFunctionArgs(name, args string) string {
105		if name != toolNameExecCommand && name != "shell" && name != "local_shell" {
106			return ""
107		}
108		if args == "" {
109			return ""
110		}
111		var v struct {
112			Cmd     string   `json:"cmd,omitempty"`
113			Command []string `json:"command,omitempty"` // some local_shell shapes use []string
114		}
115		if err := json.Unmarshal([]byte(args), &v); err != nil {
116			return ""
117		}
118		if v.Cmd != "" {
119			return v.Cmd
120		}
121		if len(v.Command) > 0 {
122			// Join as a best-effort single string for downstream regex matching.
123			return strings.Join(v.Command, " ")
124		}
125		return ""
126	}
