package claudecode

import (
	"encoding/json"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time assertion that ClaudeCodeAgent satisfies ToolCallWalker.
var _ agent.ToolCallWalker = (*ClaudeCodeAgent)(nil)

// WalkToolCalls reads Claude Code's JSONL transcript and returns one
// ToolCall per tool_use block.
func (c *ClaudeCodeAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	return agent.WalkJSONLTranscript(path, extractToolCalls)
}

func extractToolCalls(line []byte) []agent.ToolCall {
	var l struct {
		Timestamp time.Time `json:"timestamp"`
		Message   struct {
			Content []struct {
				Type  string          `json:"type"`
				Name  string          `json:"name,omitempty"`
				Input json.RawMessage `json:"input,omitempty"`
			} `json:"content"`
		} `json:"message"`
	}
	if err := json.Unmarshal(line, &l); err != nil {
		return nil
	}
	var calls []agent.ToolCall
	for _, block := range l.Message.Content {
		if block.Type != "tool_use" {
			continue
		}
		calls = append(calls, agent.ToolCall{
			Name:        block.Name,
			BashCommand: bashCommandFromInput(block.Input),
			Timestamp:   l.Timestamp,
		})
	}
	return calls
}

func bashCommandFromInput(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var v struct {
		Command string `json:"command,omitempty"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		return ""
	}
	return v.Command
}

package codex

import (
	"encoding/json"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time assertion that CodexAgent satisfies ToolCallWalker.
var _ agent.ToolCallWalker = (*CodexAgent)(nil)

// WalkToolCalls reads Codex's rollout JSONL and returns one ToolCall per
// tool-invoking response_item (function_call, custom_tool_call,
// local_shell_call, web_search_call). Token-count events, reasoning
// blocks, messages, and *_output entries are skipped — those are either
// internal state or result pairs of earlier calls.
func (c *CodexAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	return agent.WalkJSONLTranscript(path, extractToolCalls)
}

func extractToolCalls(line []byte) []agent.ToolCall {
	var rl rolloutLine
	if err := json.Unmarshal(line, &rl); err != nil {
		return nil
	}
	if rl.Type != rolloutLineTypeResponseItem {
		return nil
	}
	var payload responseItemPayload
	if err := json.Unmarshal(rl.Payload, &payload); err != nil {
		return nil
	}
	call, ok := toolCallFromPayload(payload, rl.Timestamp)
	if !ok {
		return nil
	}
	return []agent.ToolCall{call}
}

// toolCallFromPayload recognizes the four Codex tool-call payload shapes
// and returns a normalized ToolCall. Unknown payload types (messages,
// reasoning, token_count, *_output) return ok=false.
func toolCallFromPayload(p responseItemPayload, rawTimestamp string) (agent.ToolCall, bool) {
	// Timestamp parse failures fall back to zero time — tool count is
	// still accurate, only per-call duration attribution suffers.
	ts, err := time.Parse(time.RFC3339, rawTimestamp)
	if err != nil {
		ts = time.Time{}
	}

	switch p.Type {
	case "function_call":
		return agent.ToolCall{
			Name:        p.Name,
			BashCommand: commandFromFunctionArgs(p.Name, p.Arguments),
			Timestamp:   ts,
		}, true
	case "local_shell_call":
		return agent.ToolCall{
			Name:        "local_shell",
			BashCommand: commandFromFunctionArgs("local_shell", p.Arguments),
			Timestamp:   ts,
		}, true
	case "custom_tool_call":
		return agent.ToolCall{Name: p.Name, Timestamp: ts}, true
	case "web_search_call":
		return agent.ToolCall{Name: "web_search", Timestamp: ts}, true
	}
	return agent.ToolCall{}, false
}

// commandFromFunctionArgs extracts the shell command string from the
// arguments JSON for tools whose first arg is a command. Codex's
// exec_command uses {"cmd":"…"}; other tools may not have a command.
const toolNameExecCommand = "exec_command"

func commandFromFunctionArgs(name, args string) string {
	if name != toolNameExecCommand && name != "shell" && name != "local_shell" {
		return ""
	}
	if args == "" {
		return ""
	}
	var v struct {
		Cmd     string   `json:"cmd,omitempty"`
		Command []string `json:"command,omitempty"` // some local_shell shapes use []string
	}
	if err := json.Unmarshal([]byte(args), &v); err != nil {
		return ""
	}
	if v.Cmd != "" {
		return v.Cmd
	}
	if len(v.Command) > 0 {
		return strings.Join(v.Command, " ")
	}
	return ""
}

