213		return GetLastMessageID(data)
214	}
215	
216	// NormalizeTranscript normalizes user message content fields in-place from
217	// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
218	// (timestamps, thoughts, tokens, model, toolCalls, etc.).
219	//
220	// This operates on raw JSON rather than using ParseTranscript + re-marshal because
221	// GeminiMessage only captures a subset of fields (id, type, content, toolCalls).
222	// Round-tripping through the struct would silently drop fields like timestamp, model,
223	// and tokens that are present in real Gemini transcripts. The raw approach rewrites
224	// only the content values while leaving all other fields untouched.
225	func NormalizeTranscript(data []byte) ([]byte, error) {
226		var raw map[string]json.RawMessage
227		if err := json.Unmarshal(data, &raw); err != nil {
228			return nil, fmt.Errorf("failed to parse transcript: %w", err)
229		}
230	
231		messagesRaw, ok := raw["messages"]
232		if !ok {
233			return data, nil
234		}
235	
236		var messages []json.RawMessage
237		if err := json.Unmarshal(messagesRaw, &messages); err != nil {
238			return nil, fmt.Errorf("failed to parse messages: %w", err)
239		}
240	
241		changed := false
242		for i, msgRaw := range messages {
243			var msg map[string]json.RawMessage
244			if err := json.Unmarshal(msgRaw, &msg); err != nil {
245				continue
246			}
247	
248			contentRaw, hasContent := msg["content"]
249			if !hasContent || len(contentRaw) == 0 {
250				continue
251			}
252	
253			// Skip if already a string
254			var strContent string
255			if json.Unmarshal(contentRaw, &strContent) == nil {
256				continue
257			}
258	
259			// Try to convert array of {"text":"..."} to a plain string
260			var parts []struct {
261				Text string `json:"text"`
262			}
263			if json.Unmarshal(contentRaw, &parts) != nil {
264				continue
265			}
266	
267			var texts []string
268			for _, p := range parts {
269				if p.Text != "" {
270					texts = append(texts, p.Text)
271				}
272			}
273			joined := strings.Join(texts, "\n")
274			strBytes, err := json.Marshal(joined)
275			if err != nil {
276				continue
277			}
278			msg["content"] = strBytes
279			rewritten, err := json.Marshal(msg)
280			if err != nil {
281				continue
282			}
283			messages[i] = rewritten
284			changed = true
285		}
286	
287		if !changed {
288			return data, nil
289		}
290	
291		rewrittenMessages, err := json.Marshal(messages)
292		if err != nil {
293			return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
294		}
295		raw["messages"] = rewrittenMessages
296	
297		result, err := json.MarshalIndent(raw, "", "  ")
298		if err != nil {
299			return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
300		}
301		return result, nil
302	}
303	
304	// SliceFromMessage returns a Gemini transcript scoped to messages starting from
305	// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
306	// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
307	// Returns the original data if startMessageIndex <= 0.
308	// Returns nil, nil if startMessageIndex exceeds the number of messages.
309	func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
310		if len(data) == 0 || startMessageIndex <= 0 {
311			return data, nil
312		}
313	
314		t, err := ParseTranscript(data)
315		if err != nil {
316			return nil, fmt.Errorf("failed to parse transcript for slicing: %w", err)
317		}
318	
319		if startMessageIndex >= len(t.Messages) {
320			return nil, nil
321		}
322	
323		scoped := &GeminiTranscript{
324			Messages: t.Messages[startMessageIndex:],
325		}
326	
327		out, err := json.Marshal(scoped)
328		if err != nil {
329			return nil, fmt.Errorf("failed to marshal scoped transcript: %w", err)
330		}
331		return out, nil
332	}
