package geminicli

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time assertion that GeminiCLIAgent satisfies ToolCallWalker.
var _ agent.ToolCallWalker = (*GeminiCLIAgent)(nil)

// WalkToolCalls reads Gemini CLI's JSON transcript and returns one ToolCall
// per toolCalls entry across all messages. Unlike Claude Code and Codex,
// Gemini sessions are stored as a single JSON blob rather than JSONL, so this
// walker reads the whole file instead of going through agent.WalkJSONLTranscript.
func (a *GeminiCLIAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	if path == "" {
		return nil, nil
	}
	data, err := os.ReadFile(path) //nolint:gosec // path comes from session state written by the CLI
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	if len(data) == 0 {
		return nil, nil
	}

	// Local parse shape: GeminiToolCall in transcript.go intentionally omits
	// the per-call timestamp field (see the NormalizeTranscript comment about
	// keeping GeminiMessage narrow), so define a minimal shape here instead of
	// mutating the shared type.
	var t struct {
		Messages []struct {
			ToolCalls []struct {
				Name      string          `json:"name"`
				Args      json.RawMessage `json:"args,omitempty"`
				Timestamp time.Time       `json:"timestamp"`
			} `json:"toolCalls,omitempty"`
		} `json:"messages"`
	}
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse transcript: %w", err)
	}

	var calls []agent.ToolCall
	for _, msg := range t.Messages {
		for _, tc := range msg.ToolCalls {
			calls = append(calls, agent.ToolCall{
				Name:        tc.Name,
				BashCommand: bashCommandFromArgs(tc.Name, tc.Args),
				Timestamp:   tc.Timestamp,
			})
		}
	}
	return calls, nil
}

// bashCommandFromArgs extracts the shell command string from the args JSON
// for run_shell_command, Gemini's equivalent of Claude Code's Bash tool.
// Gemini uses {"command": "..."}.
const toolNameRunShell = "run_shell_command"

func bashCommandFromArgs(name string, raw json.RawMessage) string {
	if name != toolNameRunShell {
		return ""
	}
	if len(raw) == 0 {
		return ""
	}
	var v struct {
		Command string `json:"command,omitempty"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		return ""
	}
	return v.Command
}

package geminicli

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

const geminiWalkFixture = `{
  "sessionId": "s",
  "messages": [
    {"type": "user", "content": "fix it"},
    {"type": "gemini", "timestamp": "2026-04-15T10:00:00Z", "toolCalls": [
      {"id": "t1", "name": "read_file", "timestamp": "2026-04-15T10:00:05Z", "args": {"file_path": "foo.go"}},
      {"id": "t2", "name": "run_shell_command", "timestamp": "2026-04-15T10:00:10Z", "args": {"command": "ls -la"}}
    ]},
    {"type": "gemini", "timestamp": "2026-04-15T10:00:20Z", "toolCalls": [
      {"id": "t3", "name": "write_file", "timestamp": "2026-04-15T10:00:15Z", "args": {"file_path": "foo.go", "content": "x"}}
    ]}
  ]
}`

func TestWalkToolCalls_GeminiBasicShape(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "s.json")
	if err := os.WriteFile(p, []byte(geminiWalkFixture), 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 3 {
		t.Fatalf("expected 3 calls, got %d: %+v", len(calls), calls)
	}
	if calls[0].Name != "read_file" || calls[0].BashCommand != "" {
		t.Errorf("calls[0] = %+v", calls[0])
	}
	if calls[1].Name != "run_shell_command" || calls[1].BashCommand != "ls -la" {
		t.Errorf("calls[1] = %+v", calls[1])
	}
	if calls[2].Name != "write_file" || calls[2].BashCommand != "" {
		t.Errorf("calls[2] = %+v", calls[2])
	}
}

func TestWalkToolCalls_GeminiTimestamps(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "s.json")
	if err := os.WriteFile(p, []byte(geminiWalkFixture), 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	want, err := time.Parse(time.RFC3339, "2026-04-15T10:00:05Z")
	if err != nil {
		t.Fatal(err)
	}
	if !calls[0].Timestamp.Equal(want) {
		t.Errorf("calls[0].Timestamp = %v, want %v", calls[0].Timestamp, want)
	}
}

func TestWalkToolCalls_GeminiEmptyFile(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "empty.json")
	if err := os.WriteFile(p, nil, 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestWalkToolCalls_GeminiMissingFile(t *testing.T) {
	t.Parallel()
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls("/nonexistent/session.json")
	if err != nil {
		t.Errorf("missing file should be silent; got err: %v", err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestWalkToolCalls_GeminiEmptyPath(t *testing.T) {
	t.Parallel()
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls("")
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

